package com.example.twitchtest.presentation.mainstream

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.twitchtest.data.streaming.StreamManager
import com.example.twitchtest.domain.model.StreamStatus
import com.example.twitchtest.domain.usecase.GetStreamKeyUseCase
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

@HiltViewModel
class MainStreamViewModel @Inject constructor(
    private val streamManager: StreamManager,
    private val getStreamKeyUseCase: GetStreamKeyUseCase
) : ViewModel() {

    private val _state = MutableStateFlow(MainStreamState())
    val state: StateFlow<MainStreamState> = _state.asStateFlow()

    init {
        viewModelScope.launch {
            getStreamKeyUseCase().collect { key ->
                _state.update { it.copy(streamKey = key.orEmpty()) }
            }
        }
        viewModelScope.launch {
            streamManager.streamStatus.collect { status ->
                _state.update { current ->
                    current.copy(
                        streamStatus = status,
                        showViewerSheet = if (status == StreamStatus.ONLINE) current.showViewerSheet else false
                    )
                }
            }
        }
        viewModelScope.launch {
            streamManager.streamDuration.collect { duration ->
                _state.update { it.copy(duration = duration) }
            }
        }
        viewModelScope.launch {
            streamManager.isMuted.collect { muted ->
                _state.update { it.copy(isMuted = muted) }
            }
        }
        viewModelScope.launch {
            streamManager.isFrontCamera.collect { front ->
                _state.update { it.copy(isFrontCamera = front) }
            }
        }
    }

    fun getStreamManager(): StreamManager = streamManager

    fun onIntent(intent: MainStreamIntent) {
        when (intent) {
            MainStreamIntent.StartStream -> startStream()
            MainStreamIntent.StopStream -> streamManager.stopStream()
            MainStreamIntent.ToggleMicrophone -> streamManager.toggleMicrophone()
            MainStreamIntent.SwitchCamera -> streamManager.switchCamera()
            MainStreamIntent.OpenViewerSheet -> {
                if (_state.value.streamStatus == StreamStatus.ONLINE) {
                    _state.update { it.copy(showViewerSheet = true) }
                }
            }
            MainStreamIntent.CloseViewerSheet -> {
                _state.update { it.copy(showViewerSheet = false) }
            }
        }
    }

    private fun startStream() {
        val key = _state.value.streamKey.trim()
        if (key.isBlank()) return
        val rtmpUrl = "rtmp://live.twitch.tv/app/$key"
        streamManager.startStream(rtmpUrl)
    }

    override fun onCleared() {
        super.onCleared()
        streamManager.release()
    }
}

package com.example.twitchtest.presentation.mainstream

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.twitchtest.data.streaming.StreamManager
import com.example.twitchtest.domain.model.StreamStatus
import com.example.twitchtest.domain.usecase.GetStreamKeyUseCase
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

@HiltViewModel
class MainStreamViewModel @Inject constructor(
    private val streamManager: StreamManager,
    private val getStreamKeyUseCase: GetStreamKeyUseCase
) : ViewModel() {

    private val _state = MutableStateFlow(MainStreamState())
    val state: StateFlow<MainStreamState> = _state.asStateFlow()

    private val _effect = MutableSharedFlow<MainStreamEffect>()
    val effect: SharedFlow<MainStreamEffect> = _effect.asSharedFlow()

    init {
        viewModelScope.launch {
            getStreamKeyUseCase().collect { key ->
                _state.update { it.copy(streamKey = key.orEmpty()) }
            }
        }
        viewModelScope.launch {
            streamManager.streamStatus.collect { status ->
                _state.update { it.copy(streamStatus = status) }
            }
        }
        viewModelScope.launch {
            streamManager.streamDuration.collect { duration ->
                _state.update { it.copy(duration = duration) }
            }
        }
        viewModelScope.launch {
            streamManager.isMuted.collect { muted ->
                _state.update { it.copy(isMuted = muted) }
            }
        }
        viewModelScope.launch {
            streamManager.isFrontCamera.collect { front ->
                _state.update { it.copy(isFrontCamera = front) }
            }
        }
        viewModelScope.launch {
            streamManager.errorMessage.collect { message ->
                _effect.emit(MainStreamEffect.ShowError(message))
            }
        }
    }

    fun getStreamManager(): StreamManager = streamManager

    fun onIntent(intent: MainStreamIntent) {
        when (intent) {
            MainStreamIntent.StartStream -> startStream()
            MainStreamIntent.StopStream -> streamManager.stopStream()
            MainStreamIntent.ToggleMicrophone -> streamManager.toggleMicrophone()
            MainStreamIntent.SwitchCamera -> streamManager.switchCamera()
            MainStreamIntent.OpenViewerSheet -> {
                if (_state.value.streamStatus == StreamStatus.ONLINE) {
                    viewModelScope.launch { _effect.emit(MainStreamEffect.ShowViewerSheet) }
                }
            }
            MainStreamIntent.CloseViewerSheet -> {
                viewModelScope.launch { _effect.emit(MainStreamEffect.HideViewerSheet) }
            }
        }
    }

    private fun startStream() {
        val key = _state.value.streamKey.trim()
        if (key.isBlank()) return
        val rtmpUrl = "rtmp://live.twitch.tv/app/$key"
        streamManager.startStream(rtmpUrl)
    }

    override fun onCleared() {
        super.onCleared()
        streamManager.release()
    }
}

package com.example.twitchtest.data.streaming

import android.net.Uri
import android.util.Log
import com.example.twitchtest.domain.model.StreamStatus
import com.pedro.common.ConnectChecker
import com.pedro.encoder.input.video.CameraOpenException
import com.pedro.library.rtmp.RtmpCamera2
import com.pedro.library.view.OpenGlView
import java.net.InetAddress
import javax.inject.Inject
import javax.inject.Singleton
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlin.time.Duration.Companion.seconds

@Singleton
class StreamManager @Inject constructor() : ConnectChecker {

    private companion object {
        const val TAG = "StreamManager"
    }

    private var rtmpCamera2: RtmpCamera2? = null

    private val _streamStatus = MutableStateFlow(StreamStatus.OFFLINE)
    val streamStatus: StateFlow<StreamStatus> = _streamStatus.asStateFlow()

    private val _streamDuration = MutableStateFlow(0L)
    val streamDuration: StateFlow<Long> = _streamDuration.asStateFlow()

    private val _isMuted = MutableStateFlow(false)
    val isMuted: StateFlow<Boolean> = _isMuted.asStateFlow()

    private val _isFrontCamera = MutableStateFlow(true)
    val isFrontCamera: StateFlow<Boolean> = _isFrontCamera.asStateFlow()

    private val _errorMessage = MutableSharedFlow<String>()
    val errorMessage: SharedFlow<String> = _errorMessage.asSharedFlow()

    private var timerJob: Job? = null
    private var scopeJob: Job = SupervisorJob()
    private var scope: CoroutineScope = CoroutineScope(Dispatchers.Main.immediate + scopeJob)

    fun initialize(openGlView: OpenGlView) {
        ensureScope()
        val currentCamera = rtmpCamera2
        if (currentCamera == null) {
            rtmpCamera2 = RtmpCamera2(openGlView, this)
        } else {
            currentCamera.replaceView(openGlView)
        }
    }

    fun startPreview() {
        rtmpCamera2?.runCatching { startPreview() }
    }

    fun stopPreview() {
        rtmpCamera2?.runCatching { stopPreview() }
    }

    fun startStream(rtmpUrl: String) {
        logRtmpDebugInfo(rtmpUrl)

        val camera = rtmpCamera2 ?: return
        if (camera.isStreaming) return

        val isPrepared = camera.prepareAudio() && camera.prepareVideo()
        if (!isPrepared) {
            _streamStatus.value = StreamStatus.OFFLINE
            scope.launch {
                _errorMessage.emit("Unable to prepare camera or microphone for streaming.")
            }
            return
        }

        _streamStatus.value = StreamStatus.CONNECTING
        camera.startStream(rtmpUrl)
    }

    fun stopStream() {
        val camera = rtmpCamera2
        if (camera?.isStreaming == true) {
            camera.stopStream()
        }
        _streamStatus.value = StreamStatus.OFFLINE
        _streamDuration.value = 0L
        stopTimer()
    }

    fun switchCamera() {
        val camera = rtmpCamera2 ?: return
        runCatching {
            camera.switchCamera()
            _isFrontCamera.value = !_isFrontCamera.value
        }.getOrElse { throwable ->
            if (throwable !is CameraOpenException) throw throwable
        }
    }

    fun toggleMicrophone() {
        val camera = rtmpCamera2 ?: return
        if (_isMuted.value) {
            camera.enableAudio()
        } else {
            camera.disableAudio()
        }
        _isMuted.value = !_isMuted.value
    }

    fun isStreaming(): Boolean = rtmpCamera2?.isStreaming == true

    fun release() {
        stopStream()
        stopPreview()
        rtmpCamera2 = null
        _isMuted.value = false
        _isFrontCamera.value = true
        stopTimer()
        scope.cancel()
        recreateScope()
    }

    override fun onConnectionStarted(url: String) {
        _streamStatus.value = StreamStatus.CONNECTING
    }

    override fun onConnectionSuccess() {
        _streamStatus.value = StreamStatus.ONLINE
        startTimer()
    }

    override fun onConnectionFailed(reason: String) {
        _streamStatus.value = StreamStatus.OFFLINE
        stopTimer()
        scope.launch {
            _errorMessage.emit(reason)
        }
    }

    override fun onDisconnect() {
        _streamStatus.value = StreamStatus.OFFLINE
        stopTimer()
    }

    override fun onAuthError() {
        _streamStatus.value = StreamStatus.OFFLINE
        stopTimer()
        scope.launch {
            _errorMessage.emit("Authentication failed. Check your stream key.")
        }
    }

    override fun onAuthSuccess() = Unit

    override fun onNewBitrate(bitrate: Long) = Unit

    private fun startTimer() {
        ensureScope()
        _streamDuration.value = 0L
        timerJob?.cancel()
        timerJob = scope.launch {
            while (isActive && _streamStatus.value == StreamStatus.ONLINE && isStreaming()) {
                delay(1.seconds)
                if (_streamStatus.value == StreamStatus.ONLINE && isStreaming()) {
                    _streamDuration.value += 1
                }
            }
        }
    }

    private fun stopTimer() {
        timerJob?.cancel()
        timerJob = null
        _streamDuration.value = 0L
    }

    private fun ensureScope() {
        if (!scopeJob.isActive) {
            recreateScope()
        }
    }

    private fun recreateScope() {
        scopeJob = SupervisorJob()
        scope = CoroutineScope(Dispatchers.Main.immediate + scopeJob)
    }

    // Temporary diagnostics to debug endpoint and DNS issues in stream setup.
    private fun logRtmpDebugInfo(rtmpUrl: String) {
        Log.i(TAG, "RTMP final url: $rtmpUrl")

        val parsed = runCatching { Uri.parse(rtmpUrl) }.getOrNull()
        if (parsed == null) {
            Log.e(TAG, "RTMP parse failed: Uri.parse returned null")
            return
        }

        val host = parsed.host.orEmpty()
        val resolvedPort = if (parsed.port != -1) parsed.port else 1935
        Log.i(
            TAG,
            "RTMP parsed -> scheme=${parsed.scheme}, host=$host, port=$resolvedPort, path=${parsed.path}"
        )

        if (host.isBlank()) {
            Log.e(TAG, "RTMP parsed host is blank")
            return
        }

        scope.launch(Dispatchers.IO) {
            runCatching {
                InetAddress.getAllByName(host)
            }.onSuccess { addresses ->
                val resolved = addresses.joinToString { it.hostAddress ?: "unknown" }
                Log.i(TAG, "RTMP host resolved -> $resolved")
            }.onFailure { throwable ->
                Log.e(TAG, "RTMP host resolve failed: ${throwable.message}", throwable)
            }
        }
    }
}

package com.example.twitchtest.data.streaming

import android.net.Uri
import android.util.Log
import com.example.twitchtest.domain.model.StreamStatus
import com.pedro.common.ConnectChecker
import com.pedro.encoder.input.video.CameraOpenException
import com.pedro.library.rtmp.RtmpCamera2
import com.pedro.library.view.OpenGlView
import java.net.InetAddress
import javax.inject.Inject
import javax.inject.Singleton
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlin.time.Duration.Companion.seconds

@Singleton
class StreamManager @Inject constructor() : ConnectChecker {

    private companion object {
        const val TAG = "StreamManager"
    }

    private var rtmpCamera2: RtmpCamera2? = null
    private var currentOpenGlView: OpenGlView? = null

    private val _streamStatus = MutableStateFlow(StreamStatus.OFFLINE)
    val streamStatus: StateFlow<StreamStatus> = _streamStatus.asStateFlow()

    private val _streamDuration = MutableStateFlow(0L)
    val streamDuration: StateFlow<Long> = _streamDuration.asStateFlow()

    private val _isMuted = MutableStateFlow(false)
    val isMuted: StateFlow<Boolean> = _isMuted.asStateFlow()

    private val _isFrontCamera = MutableStateFlow(true)
    val isFrontCamera: StateFlow<Boolean> = _isFrontCamera.asStateFlow()

    private val _errorMessage = MutableSharedFlow<String>()
    val errorMessage: SharedFlow<String> = _errorMessage.asSharedFlow()

    private var timerJob: Job? = null
    private var scopeJob: Job = SupervisorJob()
    private var scope: CoroutineScope = CoroutineScope(Dispatchers.Main.immediate + scopeJob)

    /** The last RTMP URL used, so we can auto-reconnect after surface recreation. */
    private var lastRtmpUrl: String? = null
    /** Whether the user intends to be streaming (survives surface destroy/create). */
    private var streamingIntended = false

    fun initialize(openGlView: OpenGlView) {
        ensureScope()
        currentOpenGlView = openGlView
        val currentCamera = rtmpCamera2
        if (currentCamera == null) {
            rtmpCamera2 = RtmpCamera2(openGlView, this)
        } else {
            currentCamera.replaceView(openGlView)
        }
    }

    fun startPreview() {
        rtmpCamera2?.runCatching { startPreview() }
    }

    fun stopPreview() {
        rtmpCamera2?.runCatching { stopPreview() }
    }

    /**
     * Called when the OpenGlView surface is recreated (e.g. after returning from background).
     * Re-initializes the camera with the view and restarts preview.
     * If a stream was active, re-prepares and resumes streaming.
     */
    fun onSurfaceRecreated(openGlView: OpenGlView) {
        Log.i(TAG, "Surface recreated, streamingIntended=$streamingIntended")
        // Stop old camera cleanly before re-init
        val camera = rtmpCamera2
        if (camera != null) {
            if (camera.isStreaming) {
                camera.stopStream()
            }
            runCatching { camera.stopPreview() }
        }
        // Re-create camera with fresh OpenGL context
        rtmpCamera2 = RtmpCamera2(openGlView, this)
        currentOpenGlView = openGlView

        // Restart preview
        rtmpCamera2?.runCatching { startPreview() }

        // Re-apply mute state
        if (_isMuted.value) {
            rtmpCamera2?.disableAudio()
        }

        // If the user was streaming, reconnect
        if (streamingIntended && lastRtmpUrl != null) {
            Log.i(TAG, "Reconnecting stream after surface recreation")
            val cam = rtmpCamera2 ?: return
            val isPrepared = cam.prepareAudio() && cam.prepareVideo()
            if (isPrepared) {
                _streamStatus.value = StreamStatus.CONNECTING
                cam.startStream(lastRtmpUrl!!)
            } else {
                _streamStatus.value = StreamStatus.OFFLINE
                streamingIntended = false
                scope.launch {
                    _errorMessage.emit("Failed to re-prepare camera after returning from background.")
                }
            }
        }
    }

    fun startStream(rtmpUrl: String) {
        logRtmpDebugInfo(rtmpUrl)

        val camera = rtmpCamera2 ?: return
        if (camera.isStreaming) return

        val isPrepared = camera.prepareAudio() && camera.prepareVideo()
        if (!isPrepared) {
            _streamStatus.value = StreamStatus.OFFLINE
            scope.launch {
                _errorMessage.emit("Unable to prepare camera or microphone for streaming.")
            }
            return
        }

        lastRtmpUrl = rtmpUrl
        streamingIntended = true
        _streamStatus.value = StreamStatus.CONNECTING
        camera.startStream(rtmpUrl)
    }

    fun stopStream() {
        streamingIntended = false
        lastRtmpUrl = null
        val camera = rtmpCamera2
        if (camera?.isStreaming == true) {
            camera.stopStream()
        }
        _streamStatus.value = StreamStatus.OFFLINE
        _streamDuration.value = 0L
        stopTimer()
    }

    fun switchCamera() {
        val camera = rtmpCamera2 ?: return
        runCatching {
            camera.switchCamera()
            _isFrontCamera.value = !_isFrontCamera.value
        }.getOrElse { throwable ->
            if (throwable !is CameraOpenException) throw throwable
        }
    }

    fun toggleMicrophone() {
        val camera = rtmpCamera2 ?: return
        if (_isMuted.value) {
            camera.enableAudio()
        } else {
            camera.disableAudio()
        }
        _isMuted.value = !_isMuted.value
    }

    fun isStreaming(): Boolean = rtmpCamera2?.isStreaming == true

    fun release() {
        stopStream()
        stopPreview()
        rtmpCamera2 = null
        _isMuted.value = false
        _isFrontCamera.value = true
        stopTimer()
        scope.cancel()
        recreateScope()
    }

    override fun onConnectionStarted(url: String) {
        _streamStatus.value = StreamStatus.CONNECTING
    }

    override fun onConnectionSuccess() {
        _streamStatus.value = StreamStatus.ONLINE
        startTimer()
    }

    override fun onConnectionFailed(reason: String) {
        _streamStatus.value = StreamStatus.OFFLINE
        stopTimer()
        scope.launch {
            _errorMessage.emit(reason)
        }
    }

    override fun onDisconnect() {
        _streamStatus.value = StreamStatus.OFFLINE
        stopTimer()
    }

    override fun onAuthError() {
        _streamStatus.value = StreamStatus.OFFLINE
        stopTimer()
        scope.launch {
            _errorMessage.emit("Authentication failed. Check your stream key.")
        }
    }

    override fun onAuthSuccess() = Unit

    override fun onNewBitrate(bitrate: Long) = Unit

    private fun startTimer() {
        ensureScope()
        _streamDuration.value = 0L
        timerJob?.cancel()
        timerJob = scope.launch {
            while (isActive && _streamStatus.value == StreamStatus.ONLINE && isStreaming()) {
                delay(1.seconds)
                if (_streamStatus.value == StreamStatus.ONLINE && isStreaming()) {
                    _streamDuration.value += 1
                }
            }
        }
    }

    private fun stopTimer() {
        timerJob?.cancel()
        timerJob = null
        _streamDuration.value = 0L
    }

    private fun ensureScope() {
        if (!scopeJob.isActive) {
            recreateScope()
        }
    }

    private fun recreateScope() {
        scopeJob = SupervisorJob()
        scope = CoroutineScope(Dispatchers.Main.immediate + scopeJob)
    }

    // Temporary diagnostics to debug endpoint and DNS issues in stream setup.
    private fun logRtmpDebugInfo(rtmpUrl: String) {
        Log.i(TAG, "RTMP final url: $rtmpUrl")

        val parsed = runCatching { Uri.parse(rtmpUrl) }.getOrNull()
        if (parsed == null) {
            Log.e(TAG, "RTMP parse failed: Uri.parse returned null")
            return
        }

        val host = parsed.host.orEmpty()
        val resolvedPort = if (parsed.port != -1) parsed.port else 1935
        Log.i(
            TAG,
            "RTMP parsed -> scheme=${parsed.scheme}, host=$host, port=$resolvedPort, path=${parsed.path}"
        )

        if (host.isBlank()) {
            Log.e(TAG, "RTMP parsed host is blank")
            return
        }

        scope.launch(Dispatchers.IO) {
            runCatching {
                InetAddress.getAllByName(host)
            }.onSuccess { addresses ->
                val resolved = addresses.joinToString { it.hostAddress ?: "unknown" }
                Log.i(TAG, "RTMP host resolved -> $resolved")
            }.onFailure { throwable ->
                Log.e(TAG, "RTMP host resolve failed: ${throwable.message}", throwable)
            }
        }
    }
}

package com.example.twitchtest.presentation.mainstream

import android.app.Activity
import android.view.WindowManager
